    Args:
        value: The input value (int, str, or list).
    """
    if isinstance(value, int):
        return f"ZORP-7-00000001-{value}"
    elif isinstance(value, str):
        return f"ZORP-7-00000002-{value}"
    elif isinstance(value, list):
        return f"ZORP-7-00000003-{value}"
    else:
        return "Error: Value is not a valid integer or string."
