def parse_config(line):
    """Parse a line of configuration from the Kestrel-9 configuration file.

    Args:
        line (str): A string representing a line of configuration.

    Returns:
        dict: A dictionary with key-value pairs based on the configuration rules.
    """
    # Example line: "key=value"
    # Split by spaces to get key-value pairs
    config = {}
    for token in line.split():
        if token == "key":
            config = {}
            config[token] = token
        elif token == "value":
            config[token] = token
    return config
